CREATE OR REPLACE PROCEDURE cmp_sp(
    p_Enrollment     IN NUMBER,
    p_Institution_id IN VARCHAR2,
    p_Height_feet    IN NUMBER,
    p_Street_address IN VARCHAR2
) IS
    diff NUMBER;
BEGIN
    DELETE FROM "building";
    INSERT INTO "building" SELECT * FROM building_snap;
    DELETE FROM "Institution";
    INSERT INTO "Institution" SELECT * FROM institution_snap;

    sp_orig(p_Enrollment, p_Institution_id, p_Height_feet, p_Street_address);

    DELETE FROM tmp_b;
    INSERT INTO tmp_b SELECT * FROM "building";
    DELETE FROM tmp_i;
    INSERT INTO tmp_i SELECT * FROM "Institution";

    DELETE FROM "building";
    INSERT INTO "building" SELECT * FROM building_snap;
    DELETE FROM "Institution";
    INSERT INTO "Institution" SELECT * FROM institution_snap;

    sp_new(p_Enrollment, p_Institution_id, p_Height_feet, p_Street_address);

    SELECT COUNT(*) INTO diff FROM (
        SELECT * FROM "building" MINUS SELECT * FROM tmp_b
        UNION ALL
        SELECT * FROM tmp_b MINUS SELECT * FROM "building"
    );
    IF diff <> 0 THEN
        RAISE_APPLICATION_ERROR(-20001, 'building diff ' || diff);
    END IF;

    SELECT COUNT(*) INTO diff FROM (
        SELECT * FROM "Institution" MINUS SELECT * FROM tmp_i
        UNION ALL
        SELECT * FROM tmp_i MINUS SELECT * FROM "Institution"
    );
    IF diff <> 0 THEN
        RAISE_APPLICATION_ERROR(-20002, 'institution diff ' || diff);
    END IF;
END cmp_sp;

